class ShortTermMemory:
    def __init__(self, max_turns=10):
        self.max_turns = max_turns
        self.messages = []

    def add(self, msg):
        self.messages.append(msg)
        self.trim()

    def trim(self):
        # 始终保留 system（下标0），只裁剪历史
        if len(self.messages) > self.max_turns * 2 + 1:
            dropped = self.messages[1:-self.max_turns*2]
            summary = summarize('\n'.join(m['content'] for m in dropped))
            self.messages = [self.messages[0],
                             {'role': 'system',
                              'content': f'[历史摘要]{summary}'}] \
                            + self.messages[-self.max_turns*2:]

from collections import Counter

call_counter = Counter()

def guarded_execute(call, max_repeat=3):
    key = (call.name, str(sorted(call.args.items())))
    call_counter[key] += 1
    if call_counter[key] >= max_repeat:
        # 不再真实执行，直接给模型一个引导性错误
        return {'error': f'该调用已失败{call_counter[key]}次，'
                         '请更换工具或调整参数，或结束任务'}
    try:
        return run_tool(call)
    except Exception as e:
        return {'error': str(e)}   # 错误也要喂回模型而不是抛出中断

