import functools, time
from typing import Iterator

def retry(times=3):                      # 装饰器：失败重试
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for i in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception:
                    if i == times - 1:
                        raise
                    time.sleep(2 ** i)   # 指数退避
        return wrapper
    return deco

@retry(times=3)
def stream_answer(prompt: str) -> Iterator[str]:   # 类型提示
    for chunk in llm.stream(prompt):
        yield chunk.content               # 生成器：流式输出

