import httpx, random, time

def call_llm(messages, max_retry=3):
    with httpx.Client(timeout=httpx.Timeout(120, connect=5)) as c:
        for attempt in range(max_retry):
            try:
                r = c.post(API_URL, headers=HEADERS,
                           json={'model': 'deepseek-chat',
                                 'messages': messages})
                if r.status_code == 429:               # 限流
                    wait = int(r.headers.get('Retry-After', 5))
                    time.sleep(wait)
                    continue
                r.raise_for_status()                   # 4xx/5xx抛异常
                return r.json()
            except (httpx.NetworkError, httpx.HTTPStatusError) as e:
                if attempt == max_retry - 1:
                    raise                               # 重试耗尽
                backoff = 2 ** attempt + random.random()  # 退避+抖动
                time.sleep(backoff)

import logging, time, functools

logger = logging.getLogger('llm_app')

def log_llm_call(fn):
    @functools.wraps(fn)
    def wrapper(messages, **kw):
        t0 = time.time()
        try:
            resp = fn(messages, **kw)
            logger.info('llm_call', extra={
                'trace_id': kw.get('trace_id'),
                'model': kw.get('model'),
                'prompt_tokens': resp.usage.prompt_tokens,
                'completion_tokens': resp.usage.completion_tokens,
                'latency_ms': int((time.time()-t0)*1000),
            })
            return resp
        except Exception:
            logger.exception('llm_call_failed', extra={
                'trace_id': kw.get('trace_id')})
            raise
    return wrapper

import time

class CircuitBreaker:
    def __init__(self, fail_limit=5, cooldown=30):
        self.fails, self.fail_limit = 0, fail_limit
        self.cooldown, self.opened_at = cooldown, 0

    @property
    def open(self):
        if self.fails < self.fail_limit:
            return False
        if time.time() - self.opened_at > self.cooldown:
            self.fails = 0          # 半开：放行试探
            return False
        return True

breaker = CircuitBreaker()

def chat_with_fallback(messages):
    if not breaker.open:
        try:
            return primary_llm(messages)      # 主模型
        except Exception:
            breaker.fails += 1
            breaker.opened_at = time.time()
    return fallback_llm(messages)             # 降级: 备用模型

