def kb_agent(question, user, history):
    intent = llm_classify(question, labels=['闲聊', '检索', '操作'])

    if intent == '闲聊':
        return llm_chat(history, question)

    if intent == '检索':
        query = rewrite(question, history)        # 指代消解
        docs = hybrid_search(query, top_k=30)     # 混合召回
        docs = rerank(query, docs, top_n=5)       # 精排
        if rerank_score(docs[0]) < 0.3:           # 兜底
            return '知识库中没有找到相关信息，已为您转人工。'
        return generate_with_citation(query, docs)  # 带引用生成

    return execute_tool_flow(question, user)      # 操作类走工具

class RagPipeline:
    def __init__(self, config):
        self.cfg = config

    def answer(self, q):
        q2 = rewrite(q) if self.cfg.rewrite else q
        docs = vector_search(q2, k=self.cfg.top_k)
        if self.cfg.hybrid:
            docs = rrf_fuse(docs, bm25_search(q2))
        if self.cfg.rerank:
            docs = rerank(q2, docs, top_n=5)
        return generate(q, docs)

